@dataclass
class FormField:
    name: str
    kind: str  # text, select, checkbox, radio, textarea, number, ...
    value: str  # the default the page sets (for a radio or checkbox: the value it sends when chosen)
    label: str
    options: list[tuple[str, str]] = field(default_factory=list)  # select: (value, text)
    checked: bool = False


@dataclass
class Form:
    method: str
    action: str
    hidden: dict[str, str] = field(default_factory=dict)
    fields: list[FormField] = field(default_factory=list)
    buttons: list[tuple[str, str, str]] = field(default_factory=list)  # (name, value, label) of submit buttons

    def data(self, values: dict[str, str], button: str = "") -> list[tuple[str, str]]:
        """
        What submitting the form sends: hidden fields, each field's given value (by name; a select also by its
        option text) or the page's default, checkboxes only when ticked, and the chosen submit button (by label
        or value; the only one, or none).
        """
        out = list(self.hidden.items())
        given = {k.strip(): str(v) for k, v in values.items()}
        done: set[str] = set()
        for f in self.fields:
            if f.kind in ("checkbox", "radio"):
                if f.name in given:
                    want = given[f.name]
                    on = want.casefold() in (f.value.casefold(), f.label.casefold()) or (
                        f.kind == "checkbox" and want.casefold() in ("on", "yes", "true", "1", "checked", "ja"))
                    if on and (f.kind == "checkbox" or f.name not in done):
                        out.append((f.name, f.value))
                        done.add(f.name)
                elif f.checked:
                    out.append((f.name, f.value))
                continue
            if f.name in done:
                continue
            value = given.get(f.name, f.value)
            if f.kind == "select" and f.options:
                by_text = {t.casefold(): v for v, t in f.options}
                value = value if value in {v for v, _ in f.options} else by_text.get(value.casefold(), value)
            out.append((f.name, value))
            done.add(f.name)
        chosen = None
        if button:
            want = button.strip().casefold()
            chosen = next((b for b in self.buttons if want in (b[2].casefold(), b[1].casefold(),
                                                               f"{b[0]}={b[1]}".casefold())), None)
        elif len(self.buttons) == 1:
            chosen = self.buttons[0]
        if chosen and chosen[0]:
            out.append((chosen[0], chosen[1]))
        return out


@dataclass
class HtmlView:
    title: str
    text: str
    frames: list[str]  # iframe sources, in order (fetched by the reader and put in place)
    links: list[str]
    forms: list[Form] = field(default_factory=list)  # numbered from 1 in the text: [form N METHOD -> action]


def html_view(html: str) -> HtmlView:
    """The page's visible content as text, as the browser view shows it but without refs (see module doc)."""
    tree = _Tree()
    tree.feed(html)
    tree.close()
    root = tree.root
    styles, titles = [], []

    def gather(node: Node) -> None:
        for c in node.children:
            if isinstance(c, Node):
                if c.tag == "style":
                    styles.append(c.text())
                elif c.tag == "title" and not titles:
                    titles.append(_clean(c.text()))
                else:
                    gather(c)
    gather(root)
    hider = Hider("\n".join(styles))
    out: list[str] = []
    frames: list[str] = []
    links: list[str] = []
    forms: list[Form] = []
    emit = out.append

    def _form(node: Node) -> "Form":
        a = node.attrs
        form = Form(method=a.get("method", "get").lower(), action=a.get("action", ""))
        for d in _descendants(node):
            name, kind = d.attrs.get("name", ""), d.attrs.get("type", "text").lower()
            if d.tag == "input" and kind == "hidden":
                if name:
                    form.hidden[name] = d.attrs.get("value", "")
            elif d.tag == "button" or (d.tag == "input" and kind in ("submit", "image")):
                if d.tag == "button" and kind not in ("submit", "") and d.attrs.get("type"):
                    continue  # type=button: a script control, it submits nothing
                form.buttons.append((name, d.attrs.get("value", ""),
                                     _clean(d.text()) or _clean(d.attrs.get("value", "")) or label_of(d)))
            elif d.tag == "select" and name:
                opts = [(o.attrs.get("value", _clean(o.text())), _clean(o.text()), "selected" in o.attrs)
                        for o in _descendants(d) if o.tag == "option"]
                form.fields.append(FormField(name, "select", next((v for v, _, s in opts if s), opts[0][0] if opts else ""),
                                         label_of(d), [(v, t) for v, t, _ in opts]))
            elif d.tag == "textarea" and name:
                form.fields.append(FormField(name, "textarea", _clean(d.text()), label_of(d)))
            elif d.tag == "input" and name and kind not in ("button", "reset"):
                form.fields.append(FormField(name, kind, d.attrs.get("value", "on" if kind in ("checkbox", "radio") else ""),
                                         label_of(d), checked="checked" in d.attrs))
        return form

    def label_of(node: Node) -> str:
        for key in ("aria-label", "title"):
            if node.attrs.get(key):
                return _clean(node.attrs[key])
        if node.attrs.get("id"):
            label = _labels.get(node.attrs["id"])
            if label:
                return label
        up = node.parent
        while up is not None and up.tag != "#root":
            if up.tag == "label":
                own = _clean(_own_text(up))
                if own:
                    return own
                break
            up = up.parent
        return _clean(node.attrs.get("placeholder") or node.attrs.get("name") or "")

    def _own_text(node: Node) -> str:
        return "".join(c if isinstance(c, str) else ("" if c.tag in ("select", "option", "input", "textarea",
                                                                       "button", "style", "script")
                                                      else _own_text(c)) for c in node.children)

    _labels: dict[str, str] = {}

    def index_labels(node: Node) -> None:
        for c in node.children:
            if isinstance(c, Node):
                if c.tag == "label" and c.attrs.get("for"):
                    _labels[c.attrs["for"]] = _clean(_own_text(c))
                index_labels(c)
    index_labels(root)

    def hidden(node: Node) -> bool:
        a = node.attrs
        if a.get("role") in ("menu", "listbox") and a.get("aria-hidden") != "true":
            return False  # a closed menu: a person opens it with its button, so its entries count as shown
        if "hidden" in a or a.get("aria-hidden") == "true" or _style_hidden(a.get("style", "")):
            return True
        if node.tag == "dialog" and "open" not in a:  # closed dialogs are not rendered; pop-ups open by script
            return True
        if node.tag == "input" and a.get("type", "").lower() == "hidden":
            return True
        return hider.hides(node)

    def control(node: Node) -> str:
        a, tag = node.attrs, node.tag
        if tag == "select":
            opts = [c for c in _descendants(node) if c.tag == "option"]
            chosen = [o for o in opts if "selected" in o.attrs] or opts[:1]
            names = [_clean(o.text()) for o in opts]
            listing = " | ".join(names) if len(" | ".join(names)) <= 600 else \
                " | ".join(names[:8]) + f" | ... {len(names) - 10} more ... | " + " | ".join(names[-2:])
            return (f'[select "{label_of(node)}" name={a.get("name", "")} selected="{_clean(chosen[0].text()) if chosen else ""}"'
                    f" options: {listing}]")
        if tag == "textarea":
            return f'[textarea "{label_of(node)}" name={a.get("name", "")}]'
        if tag == "button" or (tag == "input" and a.get("type", "").lower() in ("submit", "button", "reset", "image")):
            name = _clean(node.text()) or _clean(a.get("value", "")) or label_of(node)
            target = a.get("data-url") or a.get("formaction") or ""
            named = f' name={a["name"]} value={a.get("value", "")}' if a.get("name") else ""
            return f'[button "{name}"{named}' + (f" -> {target}" if target else "") + "]"
        kind = a.get("type", "text").lower()
        if kind in ("checkbox", "radio"):
            return (f'[{kind} "{label_of(node)}" name={a.get("name", "")} value={a.get("value", "on")} '
                    f'{"checked" if "checked" in a else "unchecked"}]')
        if kind == "range":
            return f'[slider "{label_of(node)}" value={a.get("value", "")}]'
        value = "" if kind == "password" else _clean(a.get("value", ""))
        return f'[textbox "{label_of(node)}" name={a.get("name", "")} value="{value}"]'

    def walk(node: Node, pre: bool = False) -> None:
        for c in node.children:
            if isinstance(c, str):
                raw = ZW.sub("", c)
                t = raw.replace("\n", "\u2028") if pre else re.sub(r"\s+", " ", raw)
                if t.strip():
                    emit(t)
                continue
            tag, a = c.tag, c.attrs
            if tag in SKIP:
                continue
            if a.get("role") == "tooltip":
                if "hidden" not in a and a.get("aria-hidden") != "true":
                    emit(f" (tooltip: {_clean(c.text())}) ")
                continue
            if hidden(c):
                continue
            if tag in ("canvas", "img", "svg") or a.get("role") == "img":
                label = _clean(a.get("aria-label") or a.get("alt") or a.get("title") or "")
                if label:
                    emit(f" [img: {label}] ")
                continue
            if tag in ("iframe", "frame"):
                src = a.get("src", "")
                frames.append(src)
                emit(f"\n[frame {src}]\n\x00FRAME{len(frames) - 1}\x00\n[/frame]\n")
                continue
            block = tag in BLOCK
            if block:
                emit("\n")
            if re.fullmatch(r"h[1-6]", tag):
                emit("#" * int(tag[1]) + " ")
            if tag == "li":
                emit("- ")
            if tag == "a" and "href" in a:
                name = _clean(c.text()) or label_of(c) or _clean(" ".join(
                    d.attrs.get("aria-label", "") for d in _descendants(c)))
                links.append(a["href"])
                emit(f' [link "{name}" -> {a["href"]}] ')
            elif tag in ("button", "select", "textarea", "input"):
                emit(" " + control(c) + " ")
            elif tag == "form":
                method = a.get("method", "get").lower()
                forms.append(_form(c))
                emit(f"[form {len(forms)} {method.upper()} -> {a.get('action', '')}]\n")
                walk(c, pre)
                emit(f"\n[/form {len(forms)}]\n")
                if method == "get":  # a search form: its fields name the query string a reader can open
                    fields = [d for d in _descendants(c) if d.tag in ("input", "select", "textarea") and d.attrs.get("name")
                              and d.attrs.get("type", "").lower() not in ("submit", "button", "checkbox", "radio")]
                    if fields:
                        query = "&".join(f"{d.attrs['name']}={d.attrs.get('value', '') if d.tag == 'input' else ''}"
                                         for d in fields)
                        emit(f"\n[search address: {a.get('action', '') or '.'}?{query}]\n")
            else:
                walk(c, pre or tag == "pre")
                if tag == "time" and a.get("datetime"):
                    emit(f" (datetime={a['datetime']})")
                title = a.get("title")
                if title and _clean(title) not in _clean(c.text()):
                    emit(f" (title: {_clean(title)})")
            if tag in ("td", "th"):
                emit(" | ")
            if block:
                emit("\n")

    walk(root)
    text = "".join(out)
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r" *\n *", "\n", text)
    text = re.sub(r"\n{2,}", "\n", text).replace("\u2028", "\n").strip()
    return HtmlView(titles[0] if titles else "", text, frames, links, forms)


def _descendants(node: Node):
    for c in node.children:
        if isinstance(c, Node):
            yield c
            yield from _descendants(c)

